  const pending = new Map();
  let seq = 0;
  return {
    pending,
    set: (fn, ms) => {
      const id = ++seq;
      pending.set(id, { fn, ms });
      return id;
    },
    clear: (id) => pending.delete(id),
    runAll: () => {
      [...pending.keys()].forEach((id) => {
        const t = pending.get(id);
        pending.delete(id);
        if (t) t.fn();
      });
    },
  };
